import{_ as r,o,c as d,a2 as s}from"./chunks/framework.BXyf8PVu.js";const p=JSON.parse('{"title":"ESG","description":"","frontmatter":{"title":"ESG"},"headers":[],"relativePath":"zh/blogs/CFA/C4 Corporate Finance/M2 ESG.md","filePath":"zh/blogs/CFA/C4 Corporate Finance/M2 ESG.md"}'),n={name:"zh/blogs/CFA/C4 Corporate Finance/M2 ESG.md"};function g(a,t,l,e,i,h){return o(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="投资分析中的环境、社会与治理-esg-考虑" tabindex="-1">投资分析中的环境、社会与治理（ESG）考虑 <a class="header-anchor" href="#投资分析中的环境、社会与治理-esg-考虑" aria-label="Permalink to &quot;投资分析中的环境、社会与治理（ESG）考虑&quot;">​</a></h1><p>所有权结构如何塑造公司治理，如何评估公司的治理，以及如何识别 ESG 风险与机会并把它们纳入股票和信用分析。本模块以概念为主：没有需要记忆的公式。</p><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td><strong>控股股东</strong></td><td>能够行使控制权的个人或群体（家族、其他公司、国家），持有<strong>多数</strong>（&gt; 50%）<strong>或少数</strong>（&lt; 50%）股份</td></tr><tr><td><strong>委托–代理问题</strong></td><td>管理层把公司资源用于自身利益，而不是股东利益</td></tr><tr><td><strong>委托–委托问题</strong></td><td>控股股东以牺牲少数股东为代价攫取资源</td></tr><tr><td><strong>投票权上限</strong></td><td>对大额持股投票权的法律限制（政府常用来阻止外国控制战略性公司）</td></tr><tr><td><strong>连锁董事</strong></td><td>同一批人在多家公司的董事会任职（在拉丁美洲很常见）</td></tr><tr><td><strong>内部人</strong></td><td>同时也是股东的管理者和董事</td></tr><tr><td><strong>股东积极主义</strong></td><td>股东用来推动公司以某种方式行事的策略</td></tr><tr><td><strong>ESG 整合</strong></td><td>在证券和行业分析<strong>以及投资组合构建</strong>中使用定性和定量的 ESG 因素</td></tr><tr><td><strong>搁浅资产</strong></td><td>变得过时或不经济的资产，常因监管或需求转变所致</td></tr><tr><td><strong>漂绿</strong></td><td>绿色债券募集资金实际上并未资助有益环境项目的风险</td></tr></tbody></table><h2 id="所有权结构" tabindex="-1">所有权结构 <a class="header-anchor" href="#所有权结构" aria-label="Permalink to &quot;所有权结构&quot;">​</a></h2><ul><li><strong>分散所有权</strong>：股东众多，没有任何一方能单独行使控制权。</li><li><strong>集中所有权</strong>：一个股东或一个群体（控股股东）能够行使控制权。</li><li><strong>混合型</strong>：介于两者之间。</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>没有固定的百分比界线。仅凭所有权可能看不出谁控制公司：控股股东可以通过下面的安排持有<strong>多数或少数</strong>股份。（阅读材料中唯一的&quot;25%&quot;描述的是英国，那里很少有公司存在持股 25% 或以上的股东。）</p></div><p>集中所有权远为常见：OECD（2017）调查的 47 个司法管辖区中有 <strong>38 个</strong>。</p><table tabindex="0"><thead><tr><th>分类</th><th>司法管辖区</th><th>说明</th></tr></thead><tbody><tr><td><strong>分散</strong></td><td>澳大利亚、爱尔兰、英国、美国</td><td>澳大利亚：股份主要由金融机构持有；美国上市公司很少有控股股东</td></tr><tr><td><strong>混合</strong></td><td>加拿大、德国、日本、荷兰、瑞士</td><td>如德国：许多公司受严格控制，但上市股份广泛持有</td></tr><tr><td><strong>集中</strong></td><td>其余 38 个（如中国、法国、印度、巴西、韩国）</td><td>国家：中国、挪威、瑞典。家族：巴西、墨西哥、葡萄牙、韩国。企业集团：印度、俄罗斯</td></tr></tbody></table><p><strong>控制权如何超过所有权：</strong></p><ul><li><strong>横向所有权</strong>：有共同商业利益的公司（关键客户或供应商）相互持股。它支持战略联盟和长期关系。</li><li><strong>纵向（金字塔）所有权</strong>：一家公司或一个集团控制两家或更多控股公司，后者再控制经营公司。</li><li><strong>双重股权</strong>：一类股份拥有更高（或唯一）的投票权，其他类别投票权较低或没有。与金字塔结构结合时，顶层的群体可以给自己发放高投票权股份，以相对较少的持股控制经营公司。</li></ul><h3 id="不同所有权结构下的冲突" tabindex="-1">不同所有权结构下的冲突 <a class="header-anchor" href="#不同所有权结构下的冲突" aria-label="Permalink to &quot;不同所有权结构下的冲突&quot;">​</a></h3><table tabindex="0"><thead><tr><th>所有权</th><th>投票权</th><th>力量对比</th><th>主要冲突</th></tr></thead><tbody><tr><td>分散</td><td>分散</td><td>股东弱，<strong>管理层强</strong></td><td><strong>委托–代理</strong></td></tr><tr><td>集中</td><td>集中</td><td><strong>股东强</strong>，管理层弱</td><td><strong>委托–委托</strong></td></tr><tr><td>分散</td><td>集中</td><td>控股股东<strong>未持有多数</strong>（通过双重股权、金字塔）</td><td><strong>委托–委托</strong></td></tr><tr><td>集中</td><td>分散</td><td>由<strong>投票权上限</strong>造成</td><td>（阅读材料未命名）</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>控股股东<strong>减轻</strong>了委托–代理问题（他们控制董事会、任命管理层，并有监督的动力），但<strong>造成</strong>了委托–委托问题。</p></div><h3 id="有影响力的股东" tabindex="-1">有影响力的股东 <a class="header-anchor" href="#有影响力的股东" aria-label="Permalink to &quot;有影响力的股东&quot;">​</a></h3><table tabindex="0"><thead><tr><th>股东</th><th>作用与问题</th></tr></thead><tbody><tr><td><strong>银行</strong></td><td>在欧洲和亚洲常见；既是贷款人<strong>又是</strong>股东。可能推动公司以不利条件借入大额贷款，损害其他股东</td></tr><tr><td><strong>家族</strong></td><td>在拉丁美洲占主导，在亚洲和欧洲较少；常有连锁董事。<strong>+</strong> 委托–代理问题较少。<strong>−</strong> 透明度差、管理层问责弱、不重视少数股东权利、难以吸引顶尖管理者</td></tr><tr><td><strong>国有企业</strong></td><td>在战略性行业，或资本需求超出私营部门能力，或国家希望产品按设定价格或标准提供（电力、医疗）。上市国企（<strong>混合所有制</strong>）受到的市场审视较少（隐含的国家破产担保），可能以牺牲股东为代价追求公共政策</td></tr><tr><td><strong>机构投资者</strong></td><td>共同基金、养老基金、保险公司、对冲基金；有资源和专业能力做判断。在分散市场中很少大到足以控制，但通过让董事会和管理层承担责任来促进良好治理</td></tr><tr><td><strong>企业集团</strong></td><td>横向或纵向结构使控制权与所有权不成比例；交叉持股限制股份转让，把外部人挡在门外。损害少数股东的<strong>关联交易</strong>风险更高（如三星、三和、Grupo Carso）</td></tr><tr><td><strong>私募股权</strong></td><td>风险投资（早期阶段、监督）和杠杆收购公司（对成熟公司的多数控制）；可能带来公司准则和基于业绩的薪酬</td></tr><tr><td><strong>外国投资者</strong></td><td>在新兴市场中，当其持股多于本国投资者时具有影响力；来自监管更严格地区的投资者可能要求更高透明度。在监管更严格的市场交叉上市可使本地少数股东受益</td></tr><tr><td><strong>内部人</strong></td><td>持股越大 → 与股东利益越一致、越注重长期；但大额持股也可能让他们有能力保护自身利益</td></tr></tbody></table><h3 id="对治理的影响" tabindex="-1">对治理的影响 <a class="header-anchor" href="#对治理的影响" aria-label="Permalink to &quot;对治理的影响&quot;">​</a></h3><ul><li><strong>独立董事</strong>：与公司没有重大关系（雇佣、所有权或薪酬）的董事。它起源于分散所有权的司法管辖区，用以加强对管理层的监督，在安然等丑闻之后其比例上升。美国要求审计、提名和薪酬委员会全部由独立董事组成。在大多数集中所有权的司法管辖区，提名和薪酬委员会并非强制，独立董事的作用较窄。OECD 国家要求或建议设定最低人数（通常 1–3 人）或最低比例（通常 20% 到 50% 以上）。</li><li><strong>董事会结构</strong>： <ul><li><strong>单层制</strong>：由执行董事和非执行董事组成的单一董事会。最常见的结构。</li><li><strong>双层制</strong>：由监事会监督管理委员会。在阿根廷、德国和俄罗斯等国是强制的；在巴西和法国是可选的。监事会检查账簿、审阅年报、监督审计师，并设定或影响管理层薪酬；在德国，它包括利益相关者代表（银行、劳工）。</li></ul></li><li><strong>特殊投票安排</strong>：帮助少数股东参与董事的提名和选举（如巴西、印度、葡萄牙、土耳其、意大利、以色列、英国）。在英国，有控股股东的高级上市公司，其独立董事必须<strong>同时</strong>获得全体股东<strong>和</strong>非控股股东的批准。</li><li><strong>治理准则、法律和上市规则</strong>：各国准则按<strong>遵守或解释</strong>的原则运作。日本走得更远：没有外部董事的公司必须解释为什么任命外部董事不合适。没有国家准则时，适用公司法（如智利）或交易所上市规则（如印度）。</li><li><strong>尽责管理准则</strong>：主要是自愿性准则，鼓励投资者行使权利并参与公司事务。根据英国尽责管理准则，机构投资者必须监督其投资的公司，英国资产管理公司必须发布遵守或解释的声明。</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>在集中所有权下，委托–代理问题通常<strong>较小</strong>，这就是独立董事在那里作用较窄的原因。</p></div><h2 id="评估公司治理" tabindex="-1">评估公司治理 <a class="header-anchor" href="#评估公司治理" aria-label="Permalink to &quot;评估公司治理&quot;">​</a></h2><p>有效的治理可以带来更高的盈利能力和 ROE 增长、更好的融资渠道、更高且可持续的股利、良好的长期股价表现以及<strong>更低的资本成本</strong>。无效的治理会带来声誉损害、竞争力减弱、股价疲弱或波动、盈利能力下降以及<strong>更高的资本成本</strong>。</p><p>治理很难量化。先看披露的政策（包括商业道德、贿赂和腐败、举报人保护以及关联交易），然后与管理层沟通，必要时采取积极主义行动。实践中，分析师通过调整<strong>风险溢价（资本成本）或信用利差</strong>来反映治理。</p><h3 id="董事会政策与实践" tabindex="-1">董事会政策与实践 <a class="header-anchor" href="#董事会政策与实践" aria-label="Permalink to &quot;董事会政策与实践&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方面</th><th>关注什么</th></tr></thead><tbody><tr><td><strong>CEO 兼任</strong></td><td>CEO 同时担任董事长 → 董事会的监督可能受损。如果董事长不独立，可以任命一名<strong>首席独立董事</strong></td></tr><tr><td><strong>董事会独立性</strong></td><td>没有独立董事或独立董事只占少数是<strong>负面</strong>的：管理层可能为自身利益行事 → 感知风险更高</td></tr><tr><td><strong>委员会</strong></td><td>审计、治理、薪酬、提名、风险、合规。检查关键委员会是否独立：非独立或执行成员会在薪酬（薪酬委员会）、管理层选聘（提名委员会）和报告诚信（审计委员会）上造成冲突</td></tr><tr><td><strong>技能与经验</strong></td><td>技能过于集中，或多样但与核心业务无关，都可能不足。在资源类或高 ESG 风险行业，董事会通常包括环境、气候或社会方面的专家</td></tr><tr><td><strong>任期</strong></td><td>超过 <strong>10 年</strong>算长。<strong>+</strong> 对业务和管理层记录有深入了解；<strong>−</strong> 可能削弱独立性（与管理层过于亲近）并抵制变革</td></tr><tr><td><strong>构成</strong></td><td>董事的人数和多样性（职业、文化和地域背景、性别、年龄、任期）。成员过多或多样性太少都可能降低治理效果</td></tr><tr><td><strong>董事会评估</strong></td><td>自我评估或外部评估，涵盖职责、领导力、结构（包括委员会）以及董事会与管理层的关系；可能面向股东、监管机构或其他利益相关者</td></tr></tbody></table><p><strong>高管薪酬。</strong> 关注透明度；短期和长期激励标准；与公司战略的联系；以及 CEO 与普通员工之间的薪酬差距。过高的薪酬（常用 CEO 薪酬 ÷ 普通员工薪酬衡量）要对照 KPI 判断：激励是否推动了公司价值？</p><ul><li><strong>薪酬话语权（say on pay）</strong>：<strong>股东</strong>可以就薪酬投票或提供反馈。</li><li><strong>追回条款（clawback）</strong>：如果出现财务重述、不当行为、违法或风险管理失败，公司可以<strong>追回已发放的薪酬</strong>。</li></ul><p><strong>投票权。</strong> <strong>普通投票</strong>（一股一票）与<strong>双重股权</strong>相对，后者中创始人或管理者持有比公众投票权更高的股份：与少数股东存在潜在冲突。</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>分离 CEO 和董事长的职位是正面的，但不是全部：独立性低、任期长以及家族或内部人主导，仍可能使董事会软弱。</p></div><h2 id="识别-esg-因素" tabindex="-1">识别 ESG 因素 <a class="header-anchor" href="#识别-esg-因素" aria-label="Permalink to &quot;识别 ESG 因素&quot;">​</a></h2><p>主要挑战是获得<strong>相关、可比且有助于决策</strong>的信息。ESG 数据主要来自公开文件和可持续发展报告（可能经过也可能未经独立鉴证）；大多数 ESG 披露是<strong>自愿的</strong>且<strong>不一致的</strong>，尽管随着时间推移有所增加。</p><p><strong>重要性。</strong> 如果一个 ESG 问题预期会影响公司的经营、财务业绩及其证券的估值，无论正面还是负面，它就是重要的。公司可能把正面但不重要的信息称为&quot;重要&quot;，同时淡化投资者会认为重要的负面信息。</p><p><strong>投资期限。</strong> 一个问题是否重要还取决于期限：</p><ul><li>期限对<strong>信用分析师</strong>尤其重要，因为债券的期限各不相同。</li><li>在监管变化或漏油等争议事件之后，一个问题的期限可能从长期转为短期（或反之）。</li><li>例如，一家制造商面临未来更严格的环境规定：短期投资者认为对近期利润影响不大；长期投资者则预期昂贵的工厂升级或罚款。</li></ul><p><strong>按行业划分的相关因素。</strong> 治理的最佳实践在各公司间相当一致（尽管因地区而异）。对于环境和社会因素，<strong>没有全球统一的最佳实践</strong>：相关性取决于行业。能源公司更多地暴露于<strong>环境</strong>因素；银行更多地暴露于<strong>社会</strong>因素（数据安全、隐私、客户满意度）；两者都暴露于治理因素。</p><p><strong>识别 ESG 因素的三种方法</strong>（单独或组合使用）：</p><table tabindex="0"><thead><tr><th>方法</th><th>是什么</th><th>例子</th></tr></thead><tbody><tr><td><strong>专有方法</strong></td><td>分析师或公司自己的判断和工具，借助公司、新闻、行业和环保组织、劳工组织、专家和政府的信息</td><td>年报、可持续发展报告和委托书，10-K；与 TCFD 一致的气候情景披露（转型风险与物理风险）</td></tr><tr><td><strong>ESG 数据提供商</strong></td><td>供应商把公开披露转化为 ESG 评分和排名（常为行业相对），并加入一些分析师的主观评估</td><td>MSCI、Sustainalytics</td></tr><tr><td><strong>非营利倡议和报告框架</strong></td><td>关于 ESG 问题的数据、见解和工具</td><td>IIRC（标准化披露框架）、GRI（按行业的可持续发展报告标准）、SASB（统一的可持续会计准则；<strong>重要性地图</strong>）、2DII、Access to Nutrition Index</td></tr></tbody></table><p>披露从极少到数页不等，使比较变得困难。例如，GRI 针对耐用消费品以及家庭和个人用品的主题包括环境方面（材料采购、包装、塑料和化学品、产品能效）、社会方面（移民工人、产品安全、标签、电子废弃物）和其他方面（高管薪酬、治理机构中的性别、供应商筛选）。</p><h2 id="esg-整合" tabindex="-1">ESG 整合 <a class="header-anchor" href="#esg-整合" aria-label="Permalink to &quot;ESG 整合&quot;">​</a></h2><p>ESG 整合旨在识别机会并降低下行风险。</p><table tabindex="0"><thead><tr><th></th><th>股票</th><th>固定收益（信用）</th></tr></thead><tbody><tr><td>目的</td><td>识别<strong>机会并</strong>降低下行风险</td><td>主要是<strong>降低下行风险</strong>（最好的情况是按面值偿还）</td></tr><tr><td>技术</td><td>预测财务数据和比率，调整估值输入（如<strong>折现率</strong>），敏感性和情景分析</td><td>内部信用评估、预测比率、相对信用排名；相对价值、<strong>利差</strong>、<strong>久期</strong>、敏感性和情景分析</td></tr><tr><td>示例</td><td>酒店：因员工流动率高而提高营业成本。零食制造商：因改用可持续的关键原料而<strong>降低</strong>折现率</td><td>玩具制造商：诉讼损害信用比率、现金流和流动性；利差可能扩大。煤炭公司：搁浅资产风险对其 <strong>10 年期</strong>票据的影响远大于 <strong>1 年期</strong>票据</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>股票和信用的识别与整合过程相似，但<strong>重要因素及其影响不同</strong>，信用（和 CDS）的影响可能因<strong>期限</strong>而异。</p></div><h3 id="绿色债券" tabindex="-1">绿色债券 <a class="header-anchor" href="#绿色债券" aria-label="Permalink to &quot;绿色债券&quot;">​</a></h3><p><strong>绿色债券</strong>为具有环境或气候效益的项目提供资金：其募集资金被指定用于特定的绿色项目。</p><ul><li>第一只是欧洲投资银行于 <strong>2007 年</strong>发行的气候意识债券。</li><li>发行人与主承销商一起决定&quot;绿色&quot;标签，必须披露合格标准和资金用途，并可委托独立评审。<strong>绿色债券原则</strong>（2014 年；自愿性；由 ICMA 维护）为此提供指导；指数提供商、评级机构和气候债券倡议组织有各自的方法，欧盟委员会正在制定标准。</li><li>对发行人而言：额外的监控和报告成本，但投资者基础更广，发行收益率可能更低。</li><li>形式：普通公司债、项目债券、MBS/ABS 和市政债券（如加利福尼亚州 2014 年发行的 US$3 亿绿色一般责任债券，与其他 GO 债券一样以普通基金为支持）。</li><li>在其他条件相同时，与发行人的普通债券<strong>评级和估值相同</strong>：只是资金用途不同，债券持有人的追索权相同。</li><li>可能<strong>因为需求</strong>而溢价交易（利差更窄），而不是因为风险更低。</li><li>风险：<strong>漂绿</strong>（为绿色特征支付过高价格，或持有不符合环境授权的债券）和<strong>流动性</strong>（许多持有人买入并持有）。</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>绿色债券的信用风险就是发行人的信用风险。更窄的利差反映的是<strong>需求</strong>，而不是更低的违约风险。</p></div><h2 id="评估-esg-风险与机会" tabindex="-1">评估 ESG 风险与机会 <a class="header-anchor" href="#评估-esg-风险与机会" aria-label="Permalink to &quot;评估 ESG 风险与机会&quot;">​</a></h2><p>整合过程：</p><ol><li>识别公司及其行业的<strong>重要</strong> ESG 因素。</li><li>在时间维度上、在预测中以及相对同行评估这些因素。</li><li>调整财务报表和估值：</li></ol><table tabindex="0"><thead><tr><th>位置</th><th>典型的 ESG 调整</th></tr></thead><tbody><tr><td>利润表 / 现金流</td><td>收入、营业和非营业成本、利润率、盈利、资本支出</td></tr><tr><td>资产负债表</td><td>对<strong>减值资产</strong>的估计</td></tr><tr><td>股票估值</td><td>资本成本 / <strong>折现率</strong>、价格乘数、终值</td></tr><tr><td>债券估值</td><td><strong>信用利差</strong>或 CDS</td></tr></tbody></table><p>《ESG 整合指南与案例研究：股票与固定收益》（2018）框架涵盖研究（定性和定量）、证券估值、投资组合构建、资产配置、情景分析和风险管理。</p><p>阅读材料的三个案例各侧重一个支柱；其思路适用于其他行业：</p><table tabindex="0"><thead><tr><th>案例</th><th>支柱</th><th>关键指标</th><th>财务调整</th><th>估值影响</th></tr></thead><tbody><tr><td><strong>Frizzle Drinks</strong>（美国饮料）</td><td>环境</td><td><strong>用水强度</strong> = 每升产品耗水升数（为便于同行比较，按每 US$100 万收入标准化）</td><td>2009 年至 2021 年下降 27%，目标到 2025 年再降 13%。2022F COGS/收入为 40%（同行 42%），因用水减少再降 1% → 毛利率更高</td><td>盈利更高 → 股票公允价值更高；债券和 CDS 的经营现金流更好；检查较低的 ESG 风险是否<strong>已反映在利差中</strong></td></tr><tr><td><strong>Well Pharma</strong>（欧洲制药）</td><td>社会</td><td><strong>产品质量</strong>：争议事件、监管警告信、召回、罚款、通过认证的工厂比例（如 ISO 9001）</td><td>同行中记录最差（15 封警告信、5 次质量争议）。明年收入 −2%；COGS/收入 +1.3%；非营业费用增加营业利润的 4.5%。处理方式取决于问题是<strong>反复出现还是一次性</strong></td><td>股东<strong>和</strong>债券持有人的盈利与现金流都下降；品牌价值可能减值</td></tr><tr><td><strong>Sumiyoshi</strong>（日本银行）</td><td>治理</td><td>与同行比较的董事会构成；以<strong>不良贷款 / 总贷款</strong>作为治理替代指标</td><td>不良贷款率比同行高 50 个基点</td><td>股权风险溢价更高；信用利差更宽</td></tr></tbody></table><p>Well Pharma 的质量问题如何传导到财务数据：</p><table tabindex="0"><thead><tr><th>因素</th><th>财务影响</th></tr></thead><tbody><tr><td>产品质量争议</td><td>品牌受损 → 销售下降</td></tr><tr><td>监管警告信</td><td>合规成本上升</td></tr><tr><td>产品召回</td><td>收入损失；召回成本</td></tr><tr><td>监管罚款</td><td>销售退回和诉讼准备</td></tr><tr><td>通过认证的工厂比例低</td><td>质量问题、召回和成本的风险更高</td></tr></tbody></table>',53)])])}const c=r(n,[["render",g]]);export{p as __pageData,c as default};
